import java.io.IOException;
import java.math.BigDecimal;
import java.nio.file.*;
import java.text.*;
import java.time.*;
import java.time.format.*;
import java.util.*;

public class Main {
    static void cetakStruk(Pelokal p, int nomor, Instant saat, List<Baris> isi) {
        System.out.println(p.teks("judul", String.valueOf(nomor)));
        BigDecimal total = BigDecimal.ZERO;
        for (Baris b : isi) {
            System.out.println(p.teks("baris", b.nama(), b.jumlah(), p.uang(b.subtotal())));
            total = total.add(b.subtotal());
        }
        System.out.println(p.teks("total", p.uang(total)));
        System.out.println(p.teks("waktu", p.waktu(saat)));
    }

    public static void main(String[] args) throws Exception {
        Bundel.siapkan("struk",
                "", "judul=Receipt #{0}\nbaris={0} x{1,number,integer}: {2}\ntotal=Total: {0}\nwaktu=Ordered {0}\n",
                "_id", "judul=Struk #{0}\nbaris={0} x{1,number,integer}: {2}\ntotal=Total: {0}\nwaktu=Dipesan {0}\n");
        Instant saat = Instant.parse("2026-11-17T07:05:00Z");
        List<Baris> isi = List.of(new Baris("Kopi Gayo", 2, new BigDecimal("85000")), new Baris("Teh Tubruk", 1500, new BigDecimal("12")));
        Pelokal p = new Pelokal("id-ID", "Asia/Jakarta", "IDR");
        Pelokal q = new Pelokal("id-ID", "Asia/Jakarta", "USD");
        System.out.println(p.uang(new BigDecimal("12")) + " | " + q.uang(new BigDecimal("12")));
    }
}

class Pelokal {
    private final Locale locale;
    private final ZoneId zona;
    private final ResourceBundle teks;
    private final NumberFormat uang;
    private final DateTimeFormatter waktu;

    Pelokal(String tag, String zona, String mataUang) {
        this.locale = Locale.forLanguageTag(tag);
        this.zona = ZoneId.of(zona);
        this.teks = ResourceBundle.getBundle("struk", locale);
        this.uang = NumberFormat.getCurrencyInstance(locale);
        this.uang.setCurrency(Currency.getInstance(mataUang));
        this.waktu = DateTimeFormatter.ofLocalizedDateTime(FormatStyle.MEDIUM, FormatStyle.SHORT).withLocale(locale);
    }

    String teks(String kunci, Object... isian) {
        return new MessageFormat(teks.getString(kunci), locale).format(isian);
    }

    String uang(BigDecimal nilai) {
        return uang.format(nilai);
    }

    String waktu(Instant saat) {
        ZonedDateTime z = saat.atZone(zona);
        return z.format(waktu) + " " + z.format(DateTimeFormatter.ofPattern("zzz", locale));
    }
}

record Baris(String nama, int jumlah, BigDecimal harga) {
    BigDecimal subtotal() {
        return harga.multiply(BigDecimal.valueOf(jumlah));
    }
}

class Bundel {
    // Khusus praktik satu file: menulis file .properties ke folder kerja, yang ada di classpath.
    // Di proyek sungguhan, file ini disimpan di src/main/resources.
    static void siapkan(String dasar, String... akhiranDanIsi) throws IOException {
        for (String akhiran : new String[]{"", "_id", "_en", "_ja", "_ms", "_id_ID", "_en_US"}) {
            Files.deleteIfExists(Path.of(dasar + akhiran + ".properties"));
        }
        for (int i = 0; i < akhiranDanIsi.length; i += 2) {
            Files.writeString(Path.of(dasar + akhiranDanIsi[i] + ".properties"), akhiranDanIsi[i + 1]);
        }
        ResourceBundle.clearCache();
    }
}

